// SmileItem.js
import React, { Component } from 'react';

class SmileItem extends Component {
    handleClick = () => {
        this.props.onVote(this.props.smile.id);
    };

    render() {
        const { smile, votes } = this.props.smile;
        return (
            <div style={{ fontSize: '2rem', margin: '10px' }}>
                {smile} – {votes} голосів
                <button onClick={this.handleClick} style={{ marginLeft: '10px' }}>
                    Голосувати
                </button>
            </div>
        );
    }
}

export default SmileItem;
